CREATE DATABASE IF NOT EXISTS teks_leads;
USE teks_leads;
DROP TABLE IF EXISTS teks_leads_3_months;

CREATE TABLE teks_leads_3_months (
    lead_id VARCHAR(20) PRIMARY KEY,
    lead_date DATE NOT NULL,
    month CHAR(7) NOT NULL,
    source VARCHAR(50) NOT NULL,
    campaign VARCHAR(80) NOT NULL,
    course VARCHAR(50) NOT NULL,
    amount_spent DECIMAL(12,2) NOT NULL,
    leads TINYINT NOT NULL,
    interested TINYINT NOT NULL,
    not_interested TINYINT NOT NULL,
    converted TINYINT NOT NULL,
    students_joined TINYINT NOT NULL,
    revenue DECIMAL(12,2) NOT NULL,
    profit DECIMAL(12,2) NOT NULL,
    INDEX idx_date (lead_date),
    INDEX idx_month (month),
    INDEX idx_source (source),
    INDEX idx_course (course)
);

