-- Students joined by source and course
SELECT
    source,
    course,
    SUM(students_joined) AS students_joined,
    SUM(leads) AS total_leads,
    ROUND(SUM(revenue), 2) AS total_revenue
FROM teks_leads_3_months
GROUP BY source, course
ORDER BY students_joined DESC;

-- Students joined by month, source and course
SELECT
    month,
    source,
    course,
    SUM(students_joined) AS students_joined
FROM teks_leads_3_months
GROUP BY month, source, course
ORDER BY month, students_joined DESC;
